-- Protocolos aprobados del sistema de Titulación anterior (respaldo del 24-03-2021) con todos sus revisores, para generar en lote
-- las constancias de «revisor del protocolo» desde Constancias → Captura de registros externos. Un registro por alumno (si el tema
-- fue de dos, ambos) con los revisores que dictaminaron en cualquier vuelta (hasta 3 en columnas; el resto en revisores_mas).
-- Solo carga los registros: no genera constancias. Repetible: no duplica (misma licenciatura, cuenta y fecha de aprobación).
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE tit_historico_protocolos ADD COLUMN revisores_mas TEXT NULL AFTER revisor3_email', 'DO 0')
            FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'tit_historico_protocolos' AND COLUMN_NAME = 'revisores_mas');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

DROP TEMPORARY TABLE IF EXISTS tmp_prot_ant;
CREATE TEMPORARY TABLE tmp_prot_ant (
  carrera VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, alumno VARCHAR(160) NOT NULL, cuenta VARCHAR(12) NOT NULL, titulo VARCHAR(500) NOT NULL,
  fecha_inicio DATE NULL, fecha_aprobacion DATE NOT NULL,
  revisor1 VARCHAR(160) NOT NULL, revisor1_email VARCHAR(120) NOT NULL, revisor2 VARCHAR(160) NOT NULL, revisor2_email VARCHAR(120) NOT NULL,
  revisor3 VARCHAR(160) NOT NULL, revisor3_email VARCHAR(120) NOT NULL, revisores_mas TEXT NULL
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT t.carrera, t.alumno, t.cuenta, t.titulo, t.fecha_inicio, t.fecha_aprobacion, t.revisor1, t.revisor1_email, t.revisor2, t.revisor2_email, t.revisor3, t.revisor3_email, t.revisores_mas
  FROM tmp_prot_ant t WHERE NOT EXISTS (SELECT 1 FROM tit_historico_protocolos p WHERE p.carrera = t.carrera AND p.cuenta = t.cuenta AND p.fecha_aprobacion = t.fecha_aprobacion);
DROP TEMPORARY TABLE IF EXISTS tmp_prot_ant;
